parameters.jsCode:
const DOCTORS = {
  'dr-masoud': { name: 'Dr. Masoud', calendarId: '<GOOGLE_CALENDAR_ID>' },
  'dr-paria':  { name: 'Dr. Paria',  calendarId: '<GOOGLE_CALENDAR_ID>' },
  'dr-parvin': { name: 'Dr. Parvin', calendarId: '<GOOGLE_CALENDAR_ID>' },
  'dr-ali':    { name: 'Dr. Ali',    calendarId: '<GOOGLE_CALENDAR_ID>' }
};

const body = $input.first().json.body;
const doctorId = (body.doctor_id || '').toLowerCase().trim();
const doctor = DOCTORS[doctorId];

if (!doctor) return [{ json: { error: 'DOCTOR_NOT_FOUND' } }];
if (!body.new_datetime) return [{ json: { error: 'MISSING_NEW_DATETIME' } }];
if (!body.appointment_datetime && !body.appointment_id && !body.patient_name) {
  return [{ json: { error: 'MISSING_ORIGINAL_APPOINTMENT' } }];
}

let oldDtStr = body.appointment_datetime || null;
if (!oldDtStr && body.appointment_id) {
  const match = body.appointment_id.match(/CLN-(\d{4})(\d{2})(\d{2})-/);
  if (match) oldDtStr = `${match[1]}-${match[2]}-${match[3]}T00:00:00+02:00`;
}
if (!oldDtStr) return [{ json: { error: 'CANNOT_DETERMINE_ORIGINAL_DATE' } }];

if (!oldDtStr.includes('+') && !oldDtStr.includes('Z')) oldDtStr += '+02:00';

let newDtStr = body.new_datetime;
if (!newDtStr.includes('+') && !newDtStr.includes('Z')) newDtStr += '+02:00';

const newStart = new Date(newDtStr);
const newEnd = new Date(newStart.getTime() + 45 * 60 * 1000);

const oldDate = new Date(oldDtStr);
const dayStart = new Date(oldDate);
dayStart.setUTCHours(0, 0, 0, 0);
const dayEnd = new Date(dayStart.getTime() + 24 * 60 * 60 * 1000);

// Generate new appointment ID
const pad = n => String(n).padStart(2, '0');
const dateStr = `${newStart.getUTCFullYear()}${pad(newStart.getUTCMonth()+1)}${pad(newStart.getUTCDate())}`;
const rand = Math.random().toString(36).substring(2, 6).toUpperCase();
const newApptId = `CLN-${dateStr}-${rand}`;

return [{ json: {
  doctor_id: doctorId,
  doctor_name: doctor.name,
  calendar_id: doctor.calendarId,
  appointment_id: body.appointment_id || null,
  patient_name: body.patient_name || null,
  patient_phone: String(body.patient_phone || ''),
  search_start: dayStart.toISOString(),
  search_end: dayEnd.toISOString(),
  new_datetime_start: newDtStr,
  new_datetime_end: newEnd.toISOString(),
  new_appointment_id: newApptId,
  check_start: newDtStr,
  check_end: newEnd.toISOString()
}}];

const prep = $('Prepare Search').first().json;
const events = $input.all();

const apptId = prep.appointment_id;
const patientName = prep.patient_name;

const match = events.find(e => {
  const summary = e.json.summary || '';
  if (apptId && summary.includes(apptId)) return true;
  if (patientName) {
    const parts = patientName.toLowerCase().split(' ');
    if (parts.every(p => summary.toLowerCase().includes(p))) return true;
  }
  return false;
});

if (!match) return [{ json: { found: false } }];

return [{ json: {
  found: true,
  old_event_id: match.json.id,
  old_summary: match.json.summary,
  old_start: match.json.start?.dateTime || match.json.start?.date,
  calendar_id: prep.calendar_id,
  doctor_name: prep.doctor_name,
  patient_name: prep.patient_name,
  patient_phone: prep.patient_phone,
  old_appointment_id: apptId || match.json.summary?.match(/\[([^\]]+)\]/)?.[1] || 'unknown',
  new_datetime_start: prep.new_datetime_start,
  new_datetime_end: prep.new_datetime_end,
  new_appointment_id: prep.new_appointment_id,
  check_start: prep.check_start,
  check_end: prep.check_end
}}];

